package com.app.videosdk.diagnostics.model

import com.google.gson.Gson
import com.google.gson.GsonBuilder
import java.util.UUID

/**
 * Public diagnostic report generated by the MtvPlayer SDK when a playback issue is detected
 * or when manually requested.
 *
 * Contains sanitized device, network, DRM, playback performance metrics, and a bounded timeline
 * of playback events.
 */
data class MtvPlayerIssueReport(
    val reportId: String = UUID.randomUUID().toString(),
    val sessionId: String = UUID.randomUUID().toString(),
    val timestamp: Long = System.currentTimeMillis(),
    val sdkVersion: String = com.app.videosdk.BuildConfig.SDK_VERSION,
    val issueType: String,
    val severity: String,
    val message: String,
    val contentId: String? = null,
    val contentTitle: String? = null,
    val contentUrl: String? = null,
    val errorCode: String? = null,
    val errorCodeName: String? = null,
    val contentType: String? = null,
    val streamType: String? = null,
    val playbackPositionMs: Long? = null,
    val playbackDurationMs: Long? = null,
    val deviceInfo: MtvDeviceInfo? = null,
    val playbackStats: MtvPlaybackStats? = null,
    val networkInfo: MtvNetworkDiagnostics? = null,
    val drmInfo: MtvDrmDiagnostics? = null,
    val timeline: List<MtvPlaybackEvent> = emptyList(),
    val recoveryInfo: MtvRecoveryInfo? = null,
    val diagnosticAttributes: Map<String, String> = emptyMap()
) {
    /**
     * Serializes this report to a JSON string formatted for backend transmission.
     */
    fun toJson(): String {
        return gson.toJson(this)
    }

    companion object {
        private val gson: Gson by lazy {
            GsonBuilder()
                .setPrettyPrinting()
                .disableHtmlEscaping()
                .create()
        }

        /**
         * Deserializes a JSON string into an [MtvPlayerIssueReport].
         */
        fun jsonToReport(json: String): MtvPlayerIssueReport? {
            return runCatching { gson.fromJson(json, MtvPlayerIssueReport::class.java) }.getOrNull()
        }
    }
}

/**
 * Information about the Android hardware and OS environment.
 */
data class MtvDeviceInfo(
    val manufacturer: String = "Unknown",
    val model: String = "Unknown",
    val brand: String = "Unknown",
    val device: String = "Unknown",
    val androidVersion: String = "Unknown",
    val sdkInt: Int = 0,
    val screenResolution: String = "0x0"
)

/**
 * Performance metrics for the current playback session.
 */
data class MtvPlaybackStats(
    val startupDurationMs: Long = 0L,
    val timeToFirstFrameMs: Long = 0L,
    val totalBufferingEvents: Int = 0,
    val totalBufferingDurationMs: Long = 0L,
    val averageBufferingDurationMs: Long = 0L,
    val longestBufferingEventMs: Long = 0L,
    val rebufferCount: Int = 0,
    val droppedVideoFrames: Int = 0,
    val audioUnderruns: Int = 0
)

/**
 * Diagnostic details regarding network connectivity and the last failed HTTP request.
 */
data class MtvNetworkDiagnostics(
    val networkType: String = "UNKNOWN",
    val isConnected: Boolean = true,
    val lastFailedUrlSanitized: String? = null,
    val lastHttpResponseCode: Int? = null,
    val lastResourceType: String? = null
)

/**
 * Diagnostic details regarding DRM configuration and license session errors.
 */
data class MtvDrmDiagnostics(
    val drmScheme: String? = null,
    val securityLevel: String? = null,
    val licenseServerUrlSanitized: String? = null,
    val lastDrmErrorCode: String? = null
)

/**
 * Single entry in the bounded playback event timeline.
 */
data class MtvPlaybackEvent(
    val eventType: String,
    val timestamp: Long = System.currentTimeMillis(),
    val elapsedSessionTimeMs: Long = 0L,
    val playbackPositionMs: Long? = null,
    val attributes: Map<String, String> = emptyMap()
)

/**
 * Recovery attempt information detailing actions taken after a failure.
 */
data class MtvRecoveryInfo(
    val attempted: Boolean = false,
    val succeeded: Boolean = false,
    val retryCount: Int = 0,
    val recoveryAction: String? = null,
    val message: String? = null
)
